/**
 * Repairs the whitespace damage from the first codemod run WITHOUT discarding
 * anything: each affected file is regenerated by replaying the corrected
 * codemod over its committed (HEAD) contents.
 */
import { execFileSync } from 'node:child_process'
import { writeFileSync, readFileSync } from 'node:fs'

const { RULES, SKIP_LINE_PATTERNS, fixForegroundOnFill } = await import('./codemod-lib.mjs')

const changed = execFileSync('git', ['diff', '--name-only', '--', 'src'], { encoding: 'utf8' })
  .split('\n')
  .map((s) => s.trim())
  .filter((s) => /\.(tsx|ts)$/.test(s))

// Regenerated from HEAD by this script; hand edits are re-applied afterwards.
const HAND_EDITED = [
  'src/providers/index.tsx',
  'src/components/ui/Button.tsx',
  'src/components/ui/Input.tsx',
  'src/components/ui/index.tsx',
  'src/components/ui/Modal.tsx',
  'src/components/ui/OTPInput.tsx',
  'src/components/ui/PhoneInput.tsx',
  'src/components/ui/SelectableOptionRow.tsx',
  'src/components/ui/StarRatingInput.tsx',
]
const SKIP = ['src/lib/tokens.ts', 'src/lib/brand-color.ts']

function transform(source) {
  return source
    .split('\n')
    .map((line) => {
      if (SKIP_LINE_PATTERNS.some((p) => p.test(line))) return line
      let out = line
      for (const [re, rep] of RULES) out = out.replace(re, rep)
      out = fixForegroundOnFill(out)
      if (out !== line) out = out.replace(/(["'`])[ \t]+(?=[\w[])/g, '$1')
      return out
    })
    .join('\n')
}

let n = 0
const handEdited = []
for (const file of changed) {
  if (SKIP.includes(file)) continue
  const head = execFileSync('git', ['show', `HEAD:${file}`], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 })
  const rebuilt = transform(head)
  writeFileSync(file, rebuilt, 'utf8')
  n++
  if (HAND_EDITED.includes(file)) handEdited.push(file)
}

console.log(`regenerated ${n} files from HEAD with the corrected codemod`)
console.log(`\nhand edits must be re-applied to ${handEdited.length} files:`)
for (const f of handEdited) console.log('  ' + f)

// Sanity: no line should have lost its indentation.
let suspicious = 0
for (const file of changed) {
  if (SKIP.includes(file)) continue
  const head = execFileSync('git', ['show', `HEAD:${file}`], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 }).split('\n')
  const now = readFileSync(file, 'utf8').split('\n')
  if (head.length !== now.length) { console.log(`  !! line count drift: ${file}`); continue }
  for (let i = 0; i < head.length; i++) {
    const hi = (head[i].match(/^[ \t]*/) || [''])[0]
    const ni = (now[i].match(/^[ \t]*/) || [''])[0]
    if (hi !== ni) { suspicious++; if (suspicious < 6) console.log(`  indent drift ${file}:${i + 1}`) }
  }
}
console.log(`\nindentation mismatches vs HEAD: ${suspicious}`)
